  2	fn credential_field(name : String, for_diagnostics~ : Bool = false) -> Bool {
  3	  let exact_names = [
  4	    "auth", "authorization", "proxy_authorization", "cookie", "set_cookie", "password",
  5	    "passwd", "token", "access_token", "accesstoken", "refresh_token", "refreshtoken",
  6	    "id_token", "api_key", "apikey", "x_api_key", "credential", "credentials", "secret",
  7	    "client_secret", "clientsecret", "private_key", "privatekey", "aws_secret_access_key",
  8	    "azure_storage_key", "docker_auth_config", "signature", "sig", "x_amz_signature",
  9	    "x_amz_security_token", "x_goog_signature",
 10	  ]
 11	  if !for_diagnostics {
 12	    let original = name
 13	      .trim_start(chars="-")
 14	      .to_owned()
 15	      .to_lower()
 16	      .replace_all(old="-", new="_")
 17	    return exact_names.contains(original) ||
 18	      [
 19	        "_auth", "_password", "_passwd", "_token", "_secret", "_api_key", "_private_key",
 20	      ]
 21	      .iter()
 22	      .any(suffix => original.has_suffix(suffix))
 23	  }
 24	  let chars = name.trim_start(chars="-").iter().to_array()
 25	  let normalized = @buffer.Buffer(size_hint=name.length())
 26	  for i in 0..<chars.length() {
 27	    let c = chars[i]
 28	    if i > 0 &&
 29	      c >= 'A' &&
 30	      c <= 'Z' &&
 31	      (
 32	        (chars[i - 1] >= 'a' && chars[i - 1] <= 'z') ||
 33	        (chars[i - 1] >= '0' && chars[i - 1] <= '9')
 34	      ) {
 35	      normalized.write_char_utf8('_')
 36	    }
 37	    normalized.write_char_utf8(if c == '-' { '_' } else { c })
 38	  }
 39	  let name = @utf8.decode_lossy(normalized.to_bytes()).to_lower()
 40	  if name == "ssh_auth_sock" {
 41	    return false
 42	  }
 43	  if ["_enabled", "_disabled", "_count", "_mode", "_method"]
 44	    .iter()
 45	    .any(suffix => name.has_suffix(suffix)) {
 46	    return false
 47	  }
 48	  exact_names.contains(name) ||
 49	  name
 50	  .split("_")
 51	  .iter()
 52	  .any(part => {
 53	    [
 54	      "auth", "authorization", "cookie", "password", "passwd", "passphrase", "token",
 55	      "secret", "apikey", "credential", "credentials", "signature", "pairingcode",
 56	      "privatekey", "clientsecret", "accesstoken", "refreshtoken", "proxyauthorization",
 57	      "setcookie", "pat",
 58	    ].contains(part.to_owned())
 59	  }) ||
 60	  name.contains("_api_key_") ||
 61	  name.has_prefix("api_key_") ||
 62	  name.has_suffix("_api_key") ||
 63	  (
 64	    for_diagnostics &&
 65	    (
 66	      name == "access_key" ||
 67	      name.contains("_access_key_") ||
 68	      name.has_prefix("access_key_") ||
 69	      name.has_suffix("_access_key") ||
 70	      name == "storage_key" ||
 71	      name.contains("_storage_key_") ||
 72	      name.has_prefix("storage_key_") ||
 73	      name.has_suffix("_storage_key")
 74	    )
 75	  ) ||
 76	  name.contains("_private_key_") ||
 77	  name.has_prefix("private_key_") ||
 78	  name.has_suffix("_private_key") ||
 79	  name == "pairing_code" ||
 80	  name.contains("_pairing_code_") ||
 81	  name.has_prefix("pairing_code_") ||
