 85	///|
 86	fn credential_word(c : Char) -> Bool {
 87	  (c >= 'a' && c <= 'z') ||
 88	  (c >= 'A' && c <= 'Z') ||
 89	  (c >= '0' && c <= '9') ||
 90	  c == '_' ||
 91	  c == '-'
 92	}
