124	///|
125	fn credential_parameter(name : String) -> String {
126	  let chars = name.iter().to_array()
127	  let buffer = @buffer.Buffer(size_hint=name.length())
128	  let mut i = 0
129	  while i < chars.length() {
130	    if chars[i] == '%' &&
131	      i + 2 < chars.length() &&
132	      credential_hex(chars[i + 1]) is Some(hi) &&
133	      credential_hex(chars[i + 2]) is Some(lo) {
134	      buffer.write_char_utf8((hi * 16 + lo).unsafe_to_char())
135	      i += 3
136	    } else {
137	      buffer.write_char_utf8(chars[i])
138	      i += 1
139	    }
140	  }
141	  @utf8.decode_lossy(buffer.to_bytes())
142	}
