227	        i = end
228	        continue
229	      }
230	      let mut separator = end
231	      if separator < chars.length() && ['"', '\''].contains(chars[separator]) {
232	        separator += 1
233	      }
234	      while separator < chars.length() && credential_space(chars[separator]) {
235	        separator += 1
236	      }
237	      if for_diagnostics &&
