372	///|
373	fn ascii_match_at(
374	  chars : Array[Char],
375	  offset : Int32,

376	  pattern : Array[Char],
377	) -> Bool {
378	  if offset + pattern.length() > chars.length() {
379	    return false
380	  }
381	  for index in 0..<pattern.length() {
382	    let value = chars[offset + index]
383	    let lower = if value >= 'A' && value <= 'Z' {
384	      (value.to_int() + 32).unsafe_to_char()
385	    } else {
386	      value
387	    }
388	    if lower != pattern[index] {
389	      return false
390	    }
391	  }
392	  true
393	}
