395	///|
396	fn private_key_marker(
397	  chars : Array[Char],
398	  start : Int32,
399	  opening : Bool,
400	) -> (Int32, Int32)? {
401	  let prefix = (if opening { "-----begin " } else { "-----end " })
402	    .iter()
403	    .to_array()
404	  let ending = "private key-----".iter().to_array()
405	  for index in start..<chars.length() {
406	    if ascii_match_at(chars, index, prefix) {
407	      for end in (index + prefix.length())..<chars.length() {
408	        if ascii_match_at(chars, end, ending) {
409	          return Some((index, end + ending.length()))
410	        }
411	      }
412	      return None
413	    }
414	  }
415	  None
416	}
