418	///|
419	fn mask_private_key(
420	  text : String,
421	  private_key : Ref[Bool],
422	  truncated : Ref[Bool],
423	) -> String? {
424	  let chars = text.iter().to_array()
425	  if chars.is_empty() {
426	    return Some("")
427	  }
428	  let output = @buffer.Buffer(size_hint=text.length())
429	  let mut position = 0
430	  while position < chars.length() {
431	    if private_key.val {
432	      if private_key_marker(chars, position, false) is Some((_, end)) {
433	        private_key.val = false
434	        position = end
435	      } else {
436	        truncated.val = true
437	        position = chars.length()
438	      }
439	    } else if private_key_marker(chars, position, true) is Some((start, end)) {
440	      output.write_string_utf8(character_text(chars, position, start))
441	      output.write_string_utf8("[private key redacted]")
442	      private_key.val = true
443	      position = end
444	      if private_key_marker(chars, position, false) is None {
445	        truncated.val = true
446	      }
447	    } else {
448	      output.write_string_utf8(character_text(chars, position, chars.length()))
449	      position = chars.length()
450	    }
451	  }
452	  if output.length() == 0 {
453	    return None
454	  }
455	  Some(@utf8.decode_lossy(output.to_bytes()))
456	}
