458	///|
459	priv struct PrivateKeyScanner {
460	  mut active : Bool
461	  mut candidate : Bool
462	  tail : Array[Char]
463	  escape : Array[Char]
464	}
465	
466	///|
467	let private_key_begin_prefix : Array[Char] = "-----begin ".iter().to_array()
468	
469	///|
470	let private_key_end_prefix : Array[Char] = "-----end ".iter().to_array()
471	
472	///|
473	let private_key_end_marker : Array[Char] = "private key-----".iter().to_array()
474	
475	///|
476	let private_key_dashes : Array[Char] = "-----".iter().to_array()
477	
478	///|
479	fn PrivateKeyScanner::new(active : Bool) -> PrivateKeyScanner {
480	  { active, candidate: false, tail: [], escape: [], }
481	}
482	
483	///|
484	fn PrivateKeyScanner::plain(self : PrivateKeyScanner, c : Char) -> Unit {
485	  let c = if c >= 'A' && c <= 'Z' {
486	    (c.to_int() + 32).unsafe_to_char()
487	  } else {
488	    c
489	  }
490	  self.tail.push(c)
491	  if self.tail.length() > 32 {
492	    ignore(self.tail.remove(0))
493	  }
494	  let suffix = fn(pattern : Array[Char]) {
495	    self.tail.length() >= pattern.length() &&
496	    ascii_match_at(self.tail, self.tail.length() - pattern.length(), pattern)
497	  }
498	  if !self.candidate {
499	    self.candidate = suffix(
500	      if self.active {
501	        private_key_end_prefix
502	      } else {
503	        private_key_begin_prefix
504	      },
505	    )
506	  } else if suffix(private_key_end_marker) {
507	    self.active = !self.active
508	    self.candidate = false
509	    self.tail.clear()
510	  } else if suffix(private_key_dashes) {
511	    self.candidate = false
512	  }
513	}
514	
515	///|
516	fn PrivateKeyScanner::flush_escape(self : PrivateKeyScanner) -> Unit {
517	  for c in self.escape {
518	    self.plain(c)
519	  }
520	  self.escape.clear()
521	}
522	
523	///|
524	fn PrivateKeyScanner::feed(self : PrivateKeyScanner, text : String) -> Unit {
525	  for c in text.iter() {
526	    if self.escape.is_empty() {
527	      if c == '\\' {
528	        self.escape.push(c)
529	      } else {
530	        self.plain(c)
531	      }
532	    } else if self.escape.length() == 1 && c == 'u' {
533	      self.escape.push(c)
534	    } else if self.escape.length() >= 2 && credential_hex(c) is Some(_) {
535	      self.escape.push(c)
536	      if self.escape.length() == 6 {
537	        let code = credential_hex(self.escape[2]).unwrap() * 4096 +
538	          credential_hex(self.escape[3]).unwrap() * 256 +
539	          credential_hex(self.escape[4]).unwrap() * 16 +
540	          credential_hex(self.escape[5]).unwrap()
541	        if code >= 32 && code <= 126 {
542	          self.escape.clear()
543	          self.plain(code.unsafe_to_char())
544	        } else {
545	          self.flush_escape()
546	        }
547	      }
548	    } else {
549	      self.flush_escape()
550	      if c == '\\' {
551	        self.escape.push(c)
552	      } else {
553	        self.plain(c)
554	      }
555	    }
556	  }
557	}
558	
559	///|
560	fn PrivateKeyScanner::finish(self : PrivateKeyScanner) -> Bool {
561	  self.flush_escape()
562	  if self.candidate && !self.active {
563	    self.active = true
564	  }
565	  self.active
566	}
