568	///|
569	fn decode_diagnostic_escapes(text : String) -> String {
570	  let chars = text.iter().to_array()
571	  let output = @buffer.Buffer(size_hint=text.length())
572	  let mut i = 0
573	  while i < chars.length() {
574	    if chars[i] == '\\' &&
575	      i + 5 < chars.length() &&
576	      chars[i + 1] == 'u' &&
577	      credential_hex(chars[i + 2]) is Some(a) &&
578	      credential_hex(chars[i + 3]) is Some(b) &&
579	      credential_hex(chars[i + 4]) is Some(c) &&
580	      credential_hex(chars[i + 5]) is Some(d) {
581	      let value = a * 4096 + b * 256 + c * 16 + d
582	      if value >= 32 && value <= 126 {
583	        output.write_char_utf8(value.unsafe_to_char())
584	        i += 6
585	        continue
586	      }
587	    }
588	    output.write_char_utf8(chars[i])
589	    i += 1
590	  }
591	  @utf8.decode_lossy(output.to_bytes())
592	}
