594	///|
595	fn Progress::safe_message(self : Progress, text : String) -> String? {
596	  if self.protection_incomplete {
597	    self.details_truncated = true
598	    return None
599	  }
600	  guard terminal_text(text) is Some(text) else { return None }
601	  let state : Ref[Bool] = { val: self.private_key, }
602	  let truncated : Ref[Bool] = { val: false, }
603	  let masked = mask_private_key(text, state, truncated)
604	  self.private_key = REDACTED
605	  if truncated.val {
606	    self.details_truncated = true
607	  }
608	  guard masked is Some(masked) else { return None }
609	  let known = redact_known_values(masked, self.secrets)
610	  let incomplete : Ref[Bool] = { val: false, }
611	  let mut safe = redact_known_values(
612	    redact_credentials(known, incomplete~),
613	    self.secrets,
614	  )
615	  if incomplete.val {
616	    self.details_truncated = true
617	  }
618	  if safe.length() > 1024 {
619	    safe = safe[:1024].to_owned() + "… [truncated]"
620	    self.details_truncated = true
621	  }
622	  Some(safe)
623	}
