625	///|
626	fn redact_known_values(text : String, secrets : Array[String]) -> String {
627	  let chars = text.iter().to_array()
628	  let values : Array[Array[Char]] = []
629	  for secret in secrets {
630	    if secret.length() <= text.length() {
631	      values.push(secret.iter().to_array())
632	    }
633	  }
634	  let result = @buffer.Buffer(size_hint=text.length())
635	  let mut i = 0
636	  while i < chars.length() {
637	    let mut matched = 0
638	    for index in 0..<values.length() {
639	      let value = values[index]
640	      let mut matches = value.length() > 0 &&
641	        i + value.length() <= chars.length()
642	      if matches {
643	        for j in 0..<value.length() {
644	          if chars[i + j] != value[j] {
645	            matches = false
646	            break
647	          }
648	        }
649	      }
650	      if matches &&
651	        (
652	          value.length() > 10 ||
653	          i + 10 > chars.length() ||
654	          character_text(chars, i, i + 10) != "[redacted]"
655	        ) {
656	        matched = value.length()
657	        break
658	      }
659	    }
660	    if matched > 0 {
661	      result.write_string_utf8("[redacted]")
662	      i += matched
663	    } else if i + 10 <= chars.length() &&
664	      character_text(chars, i, i + 10) == "[redacted]" {
665	      result.write_string_utf8("[redacted]")
666	      i += 10
667	    } else {
668	      result.write_char_utf8(chars[i])
669	      i += 1
670	    }
671	  }
672	  @utf8.decode_lossy(result.to_bytes())
673	}

