494	///|
495	fn progress_json_text(text : String, truncated : Ref[Bool]) -> String {
496	  if !text.contains("\u001b") {
497	    return text
498	  }
499	  let parts : Array[String] = []
500	  for line in text.split("\n") {
501	    match terminal_text(line.to_owned()) {
502	      Some(safe) => parts.push(safe)
503	      None => {
504	        truncated.val = true
505	        return "[unavailable]"
506	      }
507	    }
508	  }
509	  parts.join("\n")
510	}
