548	///|
549	fn Progress::filter_output_line(
550	  self : Progress,
551	  line : String,
552	  private_key : Ref[Bool],
553	) -> String? {
554	  let event = @json.parse(line) catch { _ => Json::null() }
555	  self.learn_event(event, line)
556	  let normalized = if event != Json::null() {
557	    let truncated : Ref[Bool] = { val: false, }
558	    let value = progress_normalize_json(event, truncated, 0)
559	    if truncated.val {
560	      self.details_truncated = true
561	      let scanner = PrivateKeyScanner::new(private_key.val)
562	      scanner.feed(line)
563	      private_key.val = scanner.finish()
564	      return None
565	    }
566	    value.stringify()
567	  } else {
568	    match terminal_text(line) {
569	      Some(text) => decode_diagnostic_escapes(text)
570	      None => {
571	        self.details_truncated = true
572	        let scanner = PrivateKeyScanner::new(private_key.val)
573	        scanner.feed(line)
574	        private_key.val = scanner.finish()
575	        return None
576	      }
577	    }
578	  }
579	  let scanner = PrivateKeyScanner::new(private_key.val)
580	  scanner.feed(normalized)
581	  let scanned_private = scanner.finish()
582	  let truncated : Ref[Bool] = { val: false, }
583	  let safe = mask_private_key(normalized, private_key, truncated)
584	  if truncated.val {
585	    self.details_truncated = true
586	  }
587	  if scanned_private && !private_key.val {
588	    self.details_truncated = true
589	    private_key.val = true
590	    guard safe is Some(safe) else { return None }
591	    let chars = safe.iter().to_array()
592	    let prefix = "-----begin ".iter().to_array()
593	    for index in 0..<chars.length() {
594	      if ascii_match_at(chars, index, prefix) {
595	        return Some(character_text(chars, 0, index) + "[private key redacted]")
596	      }
597	    }
598	    return None
599	  }
600	  safe
601	}
