739	async fn Progress::stderr_line(
740	  self : Progress,
741	  line : String,
742	  statuses~ : Bool,
743	  messages~ : Bool,
744	) -> Unit {
745	  let event = @json.parse(line) catch { _ => Json::null() }
746	  if event != Json::null() {
747	    self.line(line, statuses~, messages~)
748	    let truncated : Ref[Bool] = { val: false, }
749	    let safe = diagnostic_json(event, {}, self.secrets, truncated, 0).stringify()
750	    if truncated.val {
751	      self.details_truncated = true
752	    }
753	    if field(event, "kind") == Some(Json::string("error")) ||
754	      [Some(Json::string("warn")), Some(Json::string("error"))].contains(
755	        field(event, "level"),
756	      ) ||
757	      field(event, "state") == Some(Json::string("failed")) {
758	      self.message(safe, debug=false, warning=true, emit=false)
759	    } else {
760	      self.remember_unrecognized(safe)
761	    }
762	    return
763	  } else if event == Json::null() &&
764	    (line.trim().has_prefix("[") || line.trim().has_prefix("{")) {
765	    self.details_truncated = true
766	    self.message(line, debug=false, warning=true, emit=false)
767	    return
768	  }
769	  self.line(line, statuses~, messages~)
770	}
