   105	///|
   106	fn character_text(chars : Array[Char], start : Int32, end : Int32) -> String {
   107	  let buffer = @buffer.Buffer(size_hint=end - start)
   108	  for i in start..<end {
   109	    buffer.write_char_utf8(chars[i])
   110	  }
   111	  @utf8.decode_lossy(buffer.to_bytes())
