   397	async fn Progress::message(
   398	  self : Progress,
   399	  text : String,
   400	  debug~ : Bool,
   401	  warning~ : Bool,
   402	  emit~ : Bool = true,
   403	) -> Unit {
   404	  if self.protection_incomplete {
   405	    self.details_truncated = true
   406	    self.remember(
   407	      "error detail unavailable because workspace protection values could not be read",
   408	      warning=true,
   409	    )
   410	    return
   411	  }
   412	  for line in text.split("\n") {
   413	    let text = line.trim().to_owned()
   414	    if text == "" {
   415	      continue
   416	    }
   417	    guard self.safe_message(text) is Some(safe) else {
   418	      self.details_truncated = true
   419	      continue
   420	    }
   421	    if !debug || warning {
   422	      self.remember(safe, warning~)
   423	    }
   424	    if !emit {
   425	      continue
   426	    }
   427	    if safe.has_prefix("#") {
   428	      guard safe.split_once(" ") is Some((id, rest)) &&
   429	        id.length() > 1 &&
   430	        id[1:].iter().all(c => c >= '0' && c <= '9') else {
   431	        continue
   432	      }
   433	      let detail = rest.trim().to_owned()
   434	      guard detail.has_prefix("[") ||
   435	        detail.has_prefix("DONE") ||
   436	        detail.has_prefix("ERROR") ||
   437	        detail.has_prefix("CACHED") else {
   438	        continue
   439	      }
   440	      if detail.has_prefix("ERROR") && debug && !warning {
   441	        self.remember(safe, warning=true)
   442	      }
   443	      if self.builds.get(id.to_owned()) == Some(detail) {
   444	        continue
   445	      }
   446	      if self.builds.length() < 2048 || self.builds.contains(id.to_owned()) {
   447	        self.builds.set(id.to_owned(), detail)
   448	      }
   449	      progress_message("Build " + id.to_owned() + ": " + detail)
   450	    } else if classic_build_step(safe) {
   451	      // Classic RUN output has no prefix. Only its own completion marker
   452	      // ends this mode; phase events on another pipe can arrive ahead of it.
