 786	async fn try_flush_diagnostic_recording() -> Unit {
 787	  if diagnostic_write_active.val ||
 788	    (diagnostic_pending.is_empty() && diagnostic_recording_health.dropped == 0) {
 789	    return
 790	  }
 791	  diagnostic_write_active.val = true
 792	  defer {
 793	    diagnostic_write_active.val = false
 794	  }
 795	  let mut failure_phase = "directory"
 796	  let mut waiting_for_lock = false
 797	  let mut health_changed = false
 798	  @async.with_timeout(50, async fn() {
 799	    let dir = adapter_state_home()
 800	    @fs.mkdir(dir, permission=0o700, recursive=true, allow_exist=true)
 801	    @fs.chmod(dir, 0o700)
 802	    let path = dir + "/events.jsonl"
 803	    let lock_path = dir + "/events.lock"
 804	    failure_phase = "lock"
 805	    if @fs.exists(lock_path) &&
 806	      @fs.kind(lock_path, follow_symlink=false) != @fs.FileKind::Regular {
 807	      diagnostic_recording_warning("invalid_lock", phase=failure_phase)
 808	      return
 809	    }
 810	    let lock = @fs.open(
 811	      lock_path,
 812	      mode=ReadWrite,
 813	      create_mode=OpenOrCreate,
 814	      permission=0o600,
 815	    )
 816	    defer lock.close()
 817	    if !lock.try_lock(Exclusive) {
 818	      waiting_for_lock = true
 819	      let started_waiting = @env.now()
 820	      let mut acquired = false
 821	      while !diagnostic_recording_health.incident &&
 822	            @env.now() - started_waiting < 20UL {
 823	        @async.sleep(1)
 824	        if lock.try_lock(Exclusive) {
 825	          acquired = true
 826	          break
 827	        }
 828	      }
 829	      if !acquired {
 830	        diagnostic_recording_warning("lock_busy", phase=failure_phase)
 831	        return
 832	      }
 833	      waiting_for_lock = false
 834	    }
 835	    failure_phase = "inspect"
 836	    if @fs.exists(path) &&
 837	      @fs.kind(path, follow_symlink=false) != @fs.FileKind::Regular {
 838	      diagnostic_recording_warning("invalid_store", phase=failure_phase)
 839	      return
 840	    }
 841	    let mut prefix = ""
 842	    let mut replace = false
 843	    let mut prefix_markers = 0
 844	    let mut retained : String? = None
 845	    let terminal = diagnostic_pending
 846	      .iter()
 847	      .any(pending => {
 848	        field(pending.event, "stage") == Some(Json::string("diagnostic-run")) &&
 849	        field(pending.event, "status") == Some(Json::string("finished"))
 850	      })
 851	    if @fs.exists(path) {
 852	      let file = @fs.open(path, mode=ReadOnly)
 853	      defer file.close()
 854	      let size = file.size()
 855	      if size > 262144L {
 856	        let marker = diagnostic_recording_event("rotated", "retention_limit")
 857	        set_field(
 858	          marker,
 859	          "missingThroughTime",
 860	          Json::string(@env.now().to_string()),
 861	        )
 862	        set_field(marker, "missingRange", Json::string("unknown"))
 863	        let records = diagnostic_retained_records(file, size)
 864	        retained = Some(records)
 865	        prefix = marker.stringify() + "\n" + records
 866	        prefix_markers += 1
 867	        replace = true
 868	      } else if size > 0L {
 869	        let tail = FixedArray::make(1, b'\x00')
 870	        guard file.read_at(tail, position=size - 1L) == 1 else {
 871	          raise AdapterError("Unable to inspect diagnostic record boundary")
 872	        }
 873	        if tail[0] != b'\n' {
 874	          let bytes = FixedArray::make(size.to_int(), b'\x00')
 875	          let read = file.read_at(bytes, position=0L)
 876	          let mut complete = read
 877	          while complete > 0 && bytes[complete - 1] != b'\n' {
