 889	            },
 890	          )
 891	          set_field(marker, "missingRange", Json::string("unknown"))
 892	          prefix += marker.stringify() + "\n"
 893	          prefix_markers += 1
 894	          retained = Some(
 895	            @utf8.decode_lossy(bytes.unsafe_reinterpret_as_bytes()[:complete]),
 896	          )
 897	          replace = true
 898	        }
 899	      }
 900	      if terminal && retained is None {
 901	        let bytes = FixedArray::make(size.to_int(), b'\x00')
 902	        let read = file.read_at(bytes, position=0L)
 903	        if read != size.to_int() {
