 920	        }
 921	      }
 922	    }
 923	    let recorded_drops = diagnostic_recording_health.dropped
 924	    let incident_serial = diagnostic_recording_health.incident_serial
 925	    if recorded_drops > 0 || diagnostic_recording_health.incident {
 926	      let marker = diagnostic_recording_event(
