 949	        )
 950	      } else {
 951	        set_field(marker, "completeness", Json::string("complete"))
 952	      }
 953	      if diagnostic_recording_health.phase != "" {
 954	        set_field(
 955	          marker,
 956	          "phase",
 957	          Json::string(diagnostic_recording_health.phase),
 958	        )
 959	      }
 960	      if diagnostic_recording_health.os_errno is Some(code) {
 961	        set_field(marker, "osErrno", Json::number(code.to_double()))
 962	      }
 963	      prefix += marker.stringify() + "\n"
 964	      prefix_markers += 1
 965	    }
 966	    let count = diagnostic_pending.length()
 967	    diagnostic_pending_inflight.val = count
 968	    defer {
 969	      diagnostic_pending_inflight.val = 0
 970	    }
 971	    let records = @buffer.Buffer(size_hint=4096)
 972	    for index in 0..<count {
 973	      records.write_string_utf8(
 974	        diagnostic_pending[index].event.stringify() + "\n",
 975	      )
 976	    }
 977	    let content = prefix + @utf8.decode_lossy(records.to_bytes())
 978	    failure_phase = if replace { "replace" } else { "append" }
 979	    if replace {
