 981	      defer (@fs.remove(temporary) catch { _ => () })
 982	      @fs.write_file(temporary, content, permission=0o600)
 983	      @fs.rename(temporary, path, replace=true)
 984	    } else {
 985	      @fs.write_file(
 986	        path,
 987	        content,
 988	        permission=0o600,
 989	        append=true,
 990	        create_mode=OpenOrCreate,
 991	      )
 992	    }
 993	    diagnostic_run_written_count.val += prefix_markers
 994	    for index in 0..<count {
 995	      if field(diagnostic_pending[index].event, "runId") ==
 996	        Some(Json::string(recording_run_id)) {
 997	        diagnostic_run_written_count.val += 1
 998	      }
 999	    }
1000	    for _ in 0..<count {
1001	      ignore(diagnostic_pending.remove(0))
1002	    }
1003	    diagnostic_previous_losses.clear()
1004	    diagnostic_recording_health.dropped -= recorded_drops
1005	    if diagnostic_recording_health.incident_serial == incident_serial {
1006	      diagnostic_recording_health.incident = false
1007	      health_changed = true
1008	    }
1009	  }) catch {
1010	    error =>
1011	      if !@async.is_being_cancelled() {
1012	        diagnostic_recording_warning(
1013	          if error is @async.TimeoutError && waiting_for_lock {
1014	            "lock_busy"
1015	          } else if error is @async.TimeoutError {
1016	            "store_timeout"
1017	          } else {
1018	            "store_unavailable"
1019	          },
1020	          phase=failure_phase,
1021	          os_errno?=match error {
1022	            @os_error.OSError(code, ..) => Some(code)
1023	            _ => None
1024	          },
1025	        )
1026	      }
1027	  }
1028	  if health_changed {
1029	    publish_diagnostic_health()
1030	    if diagnostic_recording_health.incident {
1031	      publish_diagnostic_health()
1032	    }
1033	  }
1034	}
