1344	///|
1345	fn diagnostic_output(
1346	  output : Bytes,
1347	  environment : Map[String, String],
1348	  protected_input? : String,
1349	  protect_all_input~ : Bool = false,
1350	  protected_secrets? : Array[String],
1351	  omitted~ : Bool = false,
1352	) -> String? {
1353	  if output.length() == 0 {
1354	    return if omitted {
1355	      Some("[error details incomplete or truncated]")
1356	    } else {
1357	      None
1358	    }
1359	  }
1360	  let limit = if output.length() > 8192 { 8192 } else { output.length() }
1361	  let incomplete = omitted || limit < output.length()
1362	  let text = @utf8.decode_lossy(output[:limit])
1363	  let safeguards : DiagnosticProtectedValues = {
1364	    secrets: [],
1365	    visited: 0,
1366	    incomplete: false,
1367	  }
1368	  if protected_input is Some(input) {
1369	    diagnostic_protected_values(
1370	      @json.parse(input),
1371	      safeguards,
1372	      text,
1373	      incomplete,
1374	      secret=protect_all_input,
1375	    ) catch {
1376	      _ => safeguards.incomplete = true
1377	    }
1378	  }
1379	  if safeguards.incomplete {
1380	    return Some(
1381	      "Error output omitted because protected input could not be fully matched\n[error details incomplete or truncated]",
1382	    )
1383	  }
1384	  Some(
1385	    diagnostic_text(
1386	      text,
1387	      environment~,
1388	      omitted=incomplete,
1389	      protected_secrets=safeguards.secrets + protected_secrets.unwrap_or([]),
1390	      incomplete_final_line=incomplete && output[limit - 1] != b'\n',
1391	    ),
1392	  )
1393	}
