1415	///|
1416	fn DiagnosticCapture::new(limit : Int32) -> DiagnosticCapture {
1417	  {
1418	    output: @buffer.Buffer(size_hint=if limit < 4096 { limit } else { 4096 }),
1419	    limit,
1420	    truncated: false,
1421	    finished: false,
1422	  }
1423	}
