1425	///|
1426	async fn DiagnosticCapture::read(
1427	  self : DiagnosticCapture,
1428	  reader : @process.ReadFromProcess,
1429	) -> Unit {
1430	  try {
1431	    while reader.read_some(max_len=4096) is Some(chunk) {
1432	      let remaining = self.limit - self.output.length()
1433	      let count = if chunk.length() < remaining {
1434	        chunk.length()
1435	      } else {
1436	        remaining
1437	      }
1438	      if count > 0 {
1439	        self.output.write_bytes(chunk[:count])
1440	      }
1441	      if count < chunk.length() {
1442	        self.truncated = true
1443	      }
1444	    }
1445	  } catch {
1446	    error =>
1447	      if @async.is_being_cancelled() {
1448	        raise error
1449	      } else {
1450	        self.truncated = true
1451	      }
1452	  }
1453	  self.finished = true
1454	}
