1456	///|
1457	async fn wait_diagnostic_captures(captures : Array[DiagnosticCapture]) -> Unit {
1458	  @async.with_timeout(250, async fn() {
1459	    while captures.iter().any(capture => !capture.finished) {
1460	      @async.sleep(5)
1461	    }
1462	  }) catch {
1463	    error => if @async.is_being_cancelled() { raise error }
1464	  }
1465	}
