1467	///|
1468	async fn diagnostic_process_output(
1469	  program : String,
1470	  args : Array[String],
1471	  environment~ : Map[String, String],
1472	  cwd? : StringView,
1473	  stdin? : &@process.ProcessInput,
1474	  stdout_limit~ : Int32,
1475	  stderr_limit~ : Int32,
1476	  stderr_capture? : DiagnosticCapture,
1477	) -> (Int32, Bytes, Bool, Bytes, Bool) {
1478	  let (out, stdout) = @process.read_from_process()
1479	  defer out.close()
1480	  let (err, stderr) = @process.read_from_process()
1481	  defer err.close()
1482	  @async.with_task_group(async fn(group) {
1483	    let child = @process.spawn(
1484	      group,
1485	      program,
1486	      args,
1487	      extra_env=environment,
1488	      inherit_env=false,
1489	      cwd?,
1490	      stdin?,
1491	      stdout~,
1492	      stderr~,
1493	    )
1494	    let output = DiagnosticCapture::new(stdout_limit)
1495	    let errors = stderr_capture.unwrap_or(DiagnosticCapture::new(stderr_limit))
1496	    group.spawn_bg(no_wait=true, async fn() { output.read(out) })
1497	    group.spawn_bg(no_wait=true, async fn() { errors.read(err) })
1498	    let status = child.wait()
1499	    if status == 0 {
1500	      while !output.finished {
1501	        @async.sleep(5)
1502	      }
1503	      wait_diagnostic_captures([errors])
1504	    } else {
1505	      wait_diagnostic_captures([output, errors])
1506	    }
1507	    (
1508	      status,
1509	      output.output.to_bytes(),
1510	      output.truncated || !output.finished,
1511	      errors.output.to_bytes(),
1512	      errors.truncated || !errors.finished,
1513	    )
1514	  })
1515	}
