1565	  let text = output.to_lower()
1566	  if text.contains("out of memory") || text.contains("cannot allocate memory") {
1567	    "memory_exhausted"
1568	  } else if text.contains("no space left on device") {
1569	    "disk_exhausted"
1570	  } else if text.contains("address already in use") ||
1571	    text.contains("addrinuse") {
1572	    "address_in_use"
1573	  } else if text.contains("permission denied (publickey") ||
1574	    text.contains("authentication failed") {
1575	    "authentication_failed"
1576	  } else if text.contains("host key verification failed") {
1577	    "host_key_failed"
1578	  } else if text.contains("connection refused") {
1579	    "connection_refused"
1580	  } else if text.contains("connection timed out") ||
1581	    text.contains("operation timed out") {
1582	    "connection_timeout"
1583	  } else if text.contains("could not resolve hostname") {
1584	    "name_resolution"
1585	  } else if text.contains("controlsocket") || text.contains("control socket") {
1586	    "control_socket"
1587	  } else if text.contains("build_vm:") {
1588	    "vm_boot"
1589	  } else if text.contains("create microsandbox vm") && text.contains("network:") {
1590	    "vm_network"
1591	  } else if text.contains("create microsandbox vm") && text.contains("mount:") {
1592	    "vm_mount"
1593	  } else if text.contains("ensure microsandbox final image") ||
1594	    text.contains("prepare microsandbox final image") {
1595	    "vm_image"
1596	  } else if text.contains("create microsandbox vm") {
1597	    "vm_create"
1598	  } else if text.contains("start microsandbox vm") {
1599	    "vm_start"
1600	  } else if text.contains("no such file or directory") ||
1601	    text.contains("not found") {
1602	    "missing_resource"
1603	  } else if text.contains("permission denied") {
1604	    "permission_denied"
1605	  } else if text.contains("database is locked") ||
1606	    text.contains("database locked") {
1607	    "database_locked"
1608	  } else if text.contains("too many open files") {
1609	    "file_limit"
1610	  } else {
1611	    "process_exit"
1612	  }
