254	            "context": required(state, "context"),
255	            "observedContext": field(value, "context").unwrap_or(Json::null()),
256	            "requestedProvider": provider,
257	            "observedProvider": actual_provider.unwrap_or(Json::null()),
258	            "reason": "outside_scope",
259	          },
260	          protected_secrets?=secrets,
261	          environment=workspace_environment(state),
262	          recording=state_recording(state) && secrets is Some(_),
263	        )
264	      }
265	      (
266	        in_scope,
267	        in_scope && field(value, "uid") == field(state, "workspaceUid"),
268	      )
269	    }
270	  }
271	}
