199	async fn invoke(
200	  mode : String,
201	  env : Map[String, String],
202	  directory : String,
203	  payload? : Json,
204	) -> (Int32, String, String) {
205	  if mode == "create" &&
206	    @fs.exists(directory + "/orca.yaml") &&
207	    @fs.read_file(directory + "/orca.yaml").text().contains("orca-server") {
208	    settings_fixture(directory, env)
209	  }
210	  let executable = integration_binary()
211	  let input = if payload is Some(value) {
212	    @fs.write_file(directory + "/stdin.json", value.stringify())
213	    Some(@process.redirect_from_file(directory + "/stdin.json"))
214	  } else {
215	    None
216	  }
217	  let (status, stdout, stderr) = @process.collect_output(
218	    executable,
219	    if (mode == "recover" || mode == "restart") && payload is None {
220	      [mode]
221	    } else {
222	      ["recipe", mode]
223	    },
224	    extra_env=env,
225	    stdin?=input,
226	  )
227	  let diagnostics = if status != 0 { fixture_process_errors(env) } else { "" }
228	  (status, stdout.text(), stderr.text() + diagnostics)
229	}
