231	///|
232	async fn fixture_process_errors(env : Map[String, String]) -> String {
233	  let diagnostics = []
234	  try {
235	    let path = env.get("XDG_STATE_HOME").unwrap() +
236	      "/orca-env-devsy/events.jsonl"
237	    for line in @fs.read_file(path).text().split("\n") {
238	      if line == "" {
239	        continue
240	      }
241	      let event = @json.parse(line.to_owned())
242	      if field(event, "status") != Some(Json::string("process-error")) {
243	        continue
244	      }
245	      let safe = Json::empty_object()
246	      for name in ["process_os", "process_utf8", "process_api"] {
247	        if field(event, "errorType") == Some(Json::string(name)) {
248	          set_field(safe, "errorType", Json::string(name))
249	        }
250	      }
251	      for name in ["read"] {
252	        if field(event, "phase") == Some(Json::string(name)) {
253	          set_field(safe, "phase", Json::string(name))
254	        }
255	      }
256	      if field(event, "osErrno") is Some(Json::Number(code, ..)) &&
257	        code > 0 &&
258	        code < 4096 &&
259	        code == code.to_int().to_double() {
260	        set_field(safe, "osErrno", Json::number(code))
261	      }
262	      diagnostics.push(safe.stringify())
263	    }
264	  } catch {
265	    _ => ()
266	  }
267	  diagnostics.join("\n")
268	}
